// --- One row per parameter ----------------------------------------------------
struct ParamDesc {
    uint16_t    id;          // permanent 14-bit ParamID == NRPN number
    const char* key;         // dotted identifier, e.g. "filter.cutoff"
    const char* name;        // full display name
    const char* label;       // short panel label
    Type        type;
    Scope       scope;       // persistence + layer instancing (see enum)
    Widget      widget;      // UI rendering hint (knob / envelope / grid)
    Curve       curve;       // normalized→engineering mapping
    float       min;         // engineering range
    float       mid;         // Seg2 midpoint value (unused otherwise: 0)
    float       max;
    float       def;         // default in engineering units;
                             // Select: option index, Toggle: 0/1
    const char* unit;        // display unit; "norm" = engine owns scaling
    bool        bipolarUi;   // display centred (does not change the math)
    uint8_t     smoothMs;    // audio-plane slew class: 0 step / 5 fast / 20 slow
    int16_t     cc;          // curated performance CC, -1 = NRPN only
    uint8_t     optionCount; // Select only
    const char* const* options;
    uint8_t     section;     // == id >> 7   (kept explicit for UI loops)
    uint8_t     group;
    Control     control;     // which physical control this binds to

    // ---- conditional visibility ----------------------------------------
    // A parameter that cannot do anything in the current engine state is
    // not DRAWN. It is NOT disabled: the engine keeps its value and a
    // patch still stores it, so toggling filter engine (say) does not
    // destroy your OBXa settings.
    //
    // visIf == kNoVisDep means ALWAYS VISIBLE. Otherwise the row is shown
    // only when parameter `visIf` currently holds one of the `visCount`
    // option indices in `visOpts`.
    //
    // The sentinel is 0xFFFF, NOT 0 -- 0x0000 is a REAL ParamID
    // (osc1.wave, the first row in the table). Using 0 as the sentinel
    // silently disabled every rule that depended on it.
    uint16_t       visIf;      // ParamID this depends on (0 = always show)
    const uint8_t* visOpts;    // option indices that make it visible
    uint8_t        visCount;
};

